return {["fb18_01"]={["down"]=[[fb18_02]],["dsc"]=[[这里因屋后的玉泉而得名，是宋代陈希夷隐居的地方。周围生着十二株大龙藤，夭矫多姿，枝干中空，就如飞龙相似，相传是希夷先生陈抟老祖所植。院内绿荫蔽日，泉石如画，流水萦回，回廊曲折。院中有清泉一股，泉水甘冽，传与山顶镇岳宫玉井相通，故名玉泉，玉泉院因此得名。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_01]],["item1"]=[[21wujuetiaozhan]],["item2"]=[[21wujuetiaozhan2]],["name"]=[[玉泉院]],["permission"]=1,["role1"]=[[fb18r01_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_02"]={["dsc"]=[[西岳华山，巍然耸立于陕西省华阴县城南。它北瞰黄河，南连秦岭，五座山峰高低错落，各据一方，远远望去，状若巨朵青莲，外围诸峰如莲瓣，中间三峰似莲蕊，因此山便因“花”得名，取名华山。又因其西临少华山，故华山又称太华。它素有「奇峰天下第一山」之称。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_02]],["item1"]=[[fb18item118]],["name"]=[[华山脚下]],["permission"]=1,["rightDown"]=[[fb18_03]],["rightUp"]=[[fb18_60]],["role1"]=[[fb18r02_1]],["role2"]=[[fb18r02_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_01]],["visible"]=1},["fb18_03"]={["down"]=[[fb18_05]],["dsc"]=[[沿着玉泉，踏过累累石涧，由山径迤逦而上，就来到了莎萝坪。从这里山路开始陡峭，南面一条迂回盘旋的山道，称作「十八盘」，通往山上。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_03]],["item1"]=[[fb18item21]],["item2"]=[[ycitem1]],["leftUp"]=[[fb18_02]],["name"]=[[莎萝坪]],["permission"]=1,["rightUp"]=[[fb18_04]],["role1"]=[[fb18r03_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_04"]={["dsc"]=[[这里是一处峡谷，每年雨季山洪爆发时就形成了一处蔚为壮观的瀑布。传说曾有位大侠在此练成绝世剑法。现在人去谷空，只剩下空寥的山谷和奔腾的洪水。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_04]],["item1"]=[[fb18item8]],["item2"]=[[2020qixihd]],["leftDown"]=[[fb18_03]],["name"]=[[山洪瀑布]],["permission"]=2,["rightDown"]=[[fb18_75]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_05"]={["down"]=[[fb18_06]],["dsc"]=[[过莎萝坪，是华山十八盘。十八盘的尽处就是“云门”了。这里刻着“仙境”、“天下第一名山”等石刻。云门之内的小盆地就是青柯坪。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_05]],["item1"]=[[dr3trigger01]],["name"]=[[云门]],["permission"]=1,["role1"]=[[fb18r05_1]],["role2"]=[[fb18r05_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_03]],["visible"]=1},["fb18_06"]={["dsc"]=[[走过崎岖的十八盘，穿过云门，就到了青柯坪。青柯坪是一山间盆地，地势略为平坦。从这里开始，上山的路都是由原地凿出的石阶。远远望见一个小小石亭，便是赌棋亭了。相传宋太祖与华夷先生曾弈棋于此，将华山作为赌注，宋太祖输了，从此华山上的土地就不须缴纳钱粮。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_06]],["name"]=[[青柯坪]],["permission"]=1,["right"]=[[fb18_07]],["role1"]=[[fb18r06_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_05]],["visible"]=1},["fb18_07"]={["dsc"]=[[从青柯坪沿石阶上山，山路到此而尽，前面山势险恶，石崖间仅有窄窄的石阶犹如天梯耸立，两边铁链斜悬，令人不寒而栗，不敢前行。北壁下大石当路，此石因此叫做回心石，再上去山道奇险，游客至此，就该回头了。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_07]],["item1"]=[[bfitem1]],["item2"]=[[ybritem2]],["item3"]=[[bf2046dj1]],["left"]=[[fb18_06]],["name"]=[[回心石]],["permission"]=1,["right"]=[[fb18_08]],["role1"]=[[fb18r07_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_08"]={["down"]=[[fb18_09]],["dsc"]=[[前面有一斜如天垂石梯的山阶，这就是赫赫有名的千尺幢，千尺幢是依一陡峭岩脊的裂缝开凿而成，斜度约七十度，高约二十米，仅容一人上落。抬头仅见一线天光，两旁岩壁陡峭，尽头是个仅能容身的方形石洞，俗称“天井”，天井旁的危崖上刻有“太华咽喉”的题刻。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_08]],["left"]=[[fb18_07]],["name"]=[[千尺幢]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_09"]={["dsc"]=[[走过千尺幢，前面又见另一要命的百尺峡，百尺峡不似千尺幢般险峻，但亦十分陡峭，岩壁两侧设有铁索以作扶拦。百尺峡又称百丈崖，是一座壁立千仞的悬崖。崖底到上面的最低的垭口处约百尺，故有是名。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_09]],["item1"]=[[cg2item1]],["name"]=[[百尺峡]],["permission"]=1,["right"]=[[fb18_10]],["role1"]=[[fb18r09_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_08]],["visible"]=1},["fb18_10"]={["dsc"]=[[百尺峡尽头，两边岩崖势欲相合，中夹两块巨石，前边一块刻有“惊心石”三字。过此回望，石上刻有“平心石”三字，示人们以险境已经过去，已进入平安之途了。顿时心情至此一舒。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_10]],["left"]=[[fb18_09]],["name"]=[[平心石]],["permission"]=1,["right"]=[[fb18_11]],["role1"]=[[fb18r10_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_84]],["visible"]=1},["fb18_11"]={["down"]=[[fb18_12]],["dsc"]=[[爬过两个要命的悬崖，可在这里稍作歇息。老君沟是一条半里多长的山沟，相传为太上老君到此，见无路可通，因而套上大青牛用铁犁犁出了这条沟作为登山通道。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_11]],["item1"]=[[dr3trigger07]],["left"]=[[fb18_10]],["name"]=[[老君沟]],["permission"]=1,["role1"]=[[fb18r11_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_12"]={["down"]=[[fb18_13]],["dsc"]=[[前面又是一处十分陡峭的山岭，上面有四只铁猿，盘踞台畔，据说以前从华山水帘洞出来的猿猴，每到这里就要返回去，连它们也感到难于超越，此岭因而得名。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_12]],["name"]=[[猢狲愁]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb18_11]],["visible"]=1},["fb18_13"]={["down"]=[[fb18_17]],["dsc"]=[[此处绝险，必须面壁挽索，贴身探足前进，步不登高，故名“上天梯”。北面是下山的路，往南面是金锁关。西面上去可以通达北峰云台峰。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_13]],["left"]=[[fb18_14]],["name"]=[[上天梯]],["permission"]=1,["role1"]=[[fb18r13_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_12]],["visible"]=1},["fb18_14"]={["dsc"]=[[华山五峰中最惊险的是北峰，北峰之上最陡峭的则是苍龙岭。此岭高约百米，宽仅一米，而登山之路则在其山脊之上，两侧脊坡光滑挺拔，其下悬崖深邃，云涛隐伏，岭体蜿蜒逶迤，体青背黑，如苍龙腾空，故有是名。岭侧有一石碑。西面是华山极险处之一，叫做“舍身崖”。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_14]],["item1"]=[[fb18item21]],["item2"]=[[fb18item14]],["left"]=[[fb18_16]],["name"]=[[苍龙岭]],["permission"]=2,["right"]=[[fb18_13]],["role1"]=[[fb18r14_1]],["role2"]=[[fb18r14_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_15]],["visible"]=1},["fb18_15"]={["down"]=[[fb18_14]],["dsc"]=[[太华北峰又名云台峰，它和南面的诸峰连成一条崎岖的长岭，构成了一条鱼椎脊似的登峰天梯。香炉峰和梁张峰拱立左右，峥嵘兀突。云台四面都是悬崖绝壁，十分险峻。峰顶建有真武宫，朝南通道上立着石牌楼两座，高镶“北峰顶”三字。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_15]],["item1"]=[[fb18item13]],["item2"]=[[fb18item115]],["name"]=[[云台峰]],["permission"]=2,["role1"]=[[fb18r15_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_16"]={["dsc"]=[[这是一段极窄极险的山崖，四周云雾飞绕，下面渊深无底。如不小心，一失足掉下去，只怕连骨头都找不到。边上有个小山洞。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_16]],["name"]=[[舍身崖]],["permission"]=2,["right"]=[[fb18_14]],["role1"]=[[fb18r16_1]],["role2"]=[[fb18r16_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_17"]={["down"]=[[fb18_18]],["dsc"]=[[金锁关山势形如一把锁，下面是一片开阔地，两旁是高耸入云的峭壁，中间一条羊肠小道。真是一夫当关，万夫莫开。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_17]],["item1"]=[[bfitem3]],["item2"]=[[ybritem1]],["item3"]=[[dr3trigger08]],["name"]=[[金锁关]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb18_13]],["visible"]=1},["fb18_18"]={["dsc"]=[[镇岳宫倚壁而构，四边松林蔽日，景色幽美。宫前有玉井，相传井中曾生千叶白莲。这里地势略为平坦，上、下山的游客多在此稍作休息再继续前行。附近有几间简陋的旅社，欲登东峰观日出者，大都于头晚歇息于此。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb18_18]],["item1"]=[[bfitem4]],["item2"]=[[dr3trigger02]],["leftDown"]=[[fb18_20]],["name"]=[[镇岳宫]],["permission"]=1,["right"]=[[fb18_23]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_17]],["visible"]=1},["fb18_20"]={["dsc"]=[[传说华山三圣母爱上了一个叫刘彦昌的书生，结为夫妇，其兄二郎神反对他们结合，将她压在华山下，她的儿子沉香长大后用斧子劈开华山，救出了母亲。旁边有一块中间裂开的大石，像用斧子劈开的一般，叫做斧劈石。传说就是沉香劈山救母的地方。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_20]],["item1"]=[[dr3wp10a]],["left"]=[[fb18_21]],["name"]=[[莲花峰小路]],["permission"]=2,["rightUp"]=[[fb18_18]],["role1"]=[[fb18r20_1]],["role2"]=[[fb18r20_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_21"]={["dsc"]=[[传说华山三圣母爱上了一个叫刘彦昌的书生，结为夫妇，其兄二郎神反对他们结合，将她压在华山下，她的儿子沉香长大后用斧子劈开华山，救出了母亲。旁边有一块中间裂开的大石，像用斧子劈开的一般，叫做斧劈石。传说就是沉香劈山救母的地方。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_21]],["left"]=[[fb18_22]],["name"]=[[沉香劈山处]],["permission"]=2,["right"]=[[fb18_20]],["role1"]=[[fb18r21_1]],["role2"]=[[fb18r21_2]],["role3"]=[[fb18r21_100]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_22"]={["dsc"]=[[太华西峰－又名莲花峰，也叫芙蓉峰，峰顶有一块巨石，状如莲花，覆盖崖巅。该处由此得名。这里悬崖陡峭，壁立千仞，登临远眺，秦川莽莽，渭、洛二水盘屈如带。峰顶有石名“摘星石”，取“手可摘星辰”之意，以状西峰之高。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_22]],["item1"]=[[fb18item101]],["name"]=[[莲花峰]],["permission"]=2,["right"]=[[fb18_21]],["role1"]=[[fb18r22_1]],["role2"]=[[fb18r22_104]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_23"]={["down"]=[[fb18_28]],["dsc"]=[[这里是华山的中峰，玉女峰。传说春秋时隐士萧史善吹洞箫，箫声引动了秦穆公女儿弄玉的爱慕，抛弃了宫廷生活，跟萧史来此隐居，故称玉女峰。这里地势略为平缓，不似其它四峰般险峻，江湖上赫赫有名的华山剑派就在此处。北面稀稀落落有十几间房子，是华山的地方，闲杂游客最好别往那里去。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_23]],["item1"]=[[fb18item9]],["left"]=[[fb18_18]],["leftDown"]=[[fb18_24]],["name"]=[[玉女峰]],["permission"]=1,["rightUp"]=[[fb18_25]],["role1"]=[[fb18r23_1]],["role2"]=[[fb18r23_2]],["role3"]=[[fb18r23_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_36]],["visible"]=1},["fb18_24"]={["dsc"]=[[玉女祠里供奉的到底是哪位玉女，有许多不同的说法，现在所能看到的只一尊呆板的石像。祠中大石上有一处深陷，凹处积水清碧，这是玉女的洗脸盆，碧水终年不干。]],["enterable"]=1,["id"]=[[fb18_24]],["item1"]=[[dr3trigger03]],["name"]=[[玉女祠]],["permission"]=2,["rightUp"]=[[fb18_23]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_25"]={["dsc"]=[[这里是华山的一条小山路，地势较为平缓，不似其它地方那么险峻。你走在这里，四周静悄悄的，你就像走进了一个世外桃源。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_25]],["leftDown"]=[[fb18_23]],["name"]=[[小山路]],["permission"]=2,["right"]=[[fb18_26]],["role1"]=[[fb18r25_100]],["role2"]=[[fb18item122]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_26"]={["dsc"]=[[这里是华山的一条小山路，地势较为平缓，不似其它地方那么险峻。你走在这里，四周静悄悄的，你就像走进了一个世外桃源。东面好像有一扇竹门。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_26]],["item1"]=[[dr3trigger05]],["left"]=[[fb18_25]],["name"]=[[小山路]],["permission"]=2,["right"]=[[fb18_27]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_27"]={["dsc"]=[[这是间整洁的厢房，因门窗常闭着，光线很昏暗。房里别无他物，只有中间放着一张收拾得舒舒服服的大床，看着就让人想睡觉。]],["enterable"]=1,["id"]=[[fb18_27]],["item1"]=[[dr3trigger04]],["left"]=[[fb18_26]],["name"]=[[华山小筑]],["permission"]=2,["right"]=[[fb18_86]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_28"]={["dsc"]=[[这里是玉女峰后山的一条山路。路边长满了翠竹，每当微风拂过，竹叶便沙沙作响，显得分外的幽静。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_28]],["item1"]=[[fb18item10]],["name"]=[[玉女峰山路]],["permission"]=1,["rightDown"]=[[fb18_29]],["role1"]=[[fb18r28_1]],["role2"]=[[fb18r28_2]],["role3"]=[[fb18r28_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_23]],["visible"]=1},["fb18_29"]={["down"]=[[fb18_30]],["dsc"]=[[这里是玉女峰后山的一条山路。路边长满了翠竹，每当微风拂过，竹叶便沙沙作响，显得分外的幽静。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb18_29]],["item1"]=[[fb18item11]],["leftUp"]=[[fb18_28]],["name"]=[[玉女峰山路]],["permission"]=1,["role1"]=[[fb18r29_1]],["role2"]=[[fb18r29_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_30"]={["dsc"]=[[这是华山的思过崖。危崖上有个山洞，是华山历代弟子犯规后囚禁受罚之所。崖上光秃秃的寸草不生，更无一株树木。这危崖自来相传是玉女发钗上的一颗珍珠，当年华山的祖师以此危崖为惩罚弟子之所，主要是此处无草无木，无虫无鸟，受罚的弟子在面壁思过之时，不致为外物所扰，心有旁鹜。]],["enterable"]=1,["id"]=[[fb18_30]],["item1"]=[[fb18item7]],["name"]=[[思过崖]],["permission"]=1,["role1"]=[[fb18r30_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_29]],["visible"]=1},["fb18_31"]={["down"]=[[fb18_32]],["dsc"]=[[这里便是犯错误华山弟子受罚思过的地方。位于玉女峰顶，正好有一小块平地，一面是深不可测的山谷、一面是陡峭的悬壁，零零落落的有几块山石。其中一块特别光滑，想是弟子在面壁是久坐而成。]],["enterable"]=1,["id"]=[[fb18_31]],["left"]=[[fb18_30]],["name"]=[[思过崖洞口]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_32"]={["dsc"]=[[山洞内有块光溜溜的大石，不知道曾有多少华山的前辈在此思过面壁，以致这块大石竟被坐得滑溜。石壁左侧刻着「风清扬」三个大字，是以利器所刻，笔划苍劲，深有半寸。这三字刻得劲力非凡，想必其人武功一定十分了得。]],["enterable"]=1,["id"]=[[fb18_32]],["leftDown"]=[[fb18_33]],["name"]=[[山洞]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb18_31]],["visible"]=1},["fb18_33"]={["down"]=[[fb18_34]],["dsc"]=[[这是一个毫不起眼的山洞，但是里面的石壁上却画满了五岳山宗所有已经失传的精妙绝招。花岗岩石壁上很多小人，全是用利器刻制，想见当初运力之人内力十分深厚。]],["enterable"]=1,["id"]=[[fb18_33]],["name"]=[[山洞]],["permission"]=2,["rightUp"]=[[fb18_32]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_34"]={["down"]=[[fb18_35]],["dsc"]=[[栈道以铁斜插，上覆青石板，宽不足八寸。上乃绝壁，下亦绝壁。挽索登其上，只听山风呼啸，林涛怒吼。远处偶传一两声禽鸣兽嘶，更使人毛骨悚然。踏上悬空的栈道，紧攀铁索，屏息静气，缓步挪动，才能过去。]],["enterable"]=1,["id"]=[[fb18_34]],["item1"]=[[fb18item12]],["name"]=[[长空栈道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb18_33]],["visible"]=1},["fb18_35"]={["dsc"]=[[南峰又名落雁峰，是华山最高峰。峰头题刻极多，如“太华峰头”、“竣极于天”、“袖拂天星”等，极言华岳之高。环顾四周，皆在足下。寇准诗赞曰:只有天在上，更无山与齐；举头红日近，回首白云低。传说五代时候的隐士陈抟就隐居在这里。]],["enterable"]=1,["id"]=[[fb18_35]],["name"]=[[落雁峰]],["permission"]=2,["right"]=[[fb18_83]],["role1"]=[[fb18r35_1]],["role2"]=[[fb18r35_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_34]],["visible"]=1},["fb18_36"]={["down"]=[[fb18_23]],["dsc"]=[[这里是华山的练武场，场上立这几个木人，东边是兵器库，西边是个小店。通常有许多华山弟子在此习武练剑。北边的房屋门上挂着一块匾，上书「群仙观」，西北方似乎有条小道通往山上。]],["enterable"]=1,["fightBackground"]=[[擂台]],["id"]=[[fb18_36]],["left"]=[[fb18_37]],["leftUp"]=[[fb18_39]],["name"]=[[练武场]],["permission"]=2,["right"]=[[fb18_38]],["role1"]=[[fb18r36_1]],["role2"]=[[fb18r36_2]],["role3"]=[[fb18r36_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_44]],["visible"]=1},["fb18_37"]={["dsc"]=[[这里是华山山顶的一间小店，卖些简单的饮食，专门赚那些游客的钱。]],["enterable"]=1,["id"]=[[fb18_37]],["item1"]=[[dr3trigger06]],["name"]=[[山顶小店]],["permission"]=2,["right"]=[[fb18_36]],["role1"]=[[fb18r37_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_38"]={["dsc"]=[[这里是华山的兵器房，四周放这几个兵器架，上面是华山各弟子平时练剑用的竹剑。]],["enterable"]=1,["id"]=[[fb18_38]],["left"]=[[fb18_36]],["name"]=[[兵器房]],["permission"]=2,["role1"]=[[fb18r38_1]],["role2"]=[[fb18r38_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_39"]={["dsc"]=[[这里是朝阳峰小路，山势陡峭，两边下临深谷，一不小心都会掉了下去。]],["enterable"]=1,["id"]=[[fb18_39]],["item1"]=[[fb18item21]],["name"]=[[朝阳峰小路]],["permission"]=2,["rightDown"]=[[fb18_36]],["rightUp"]=[[fb18_40]],["role1"]=[[fb18r39_1]],["role2"]=[[fb18r39_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_40"]={["dsc"]=[[紫气台终年云遮雾掩，迷蒙不见天日，更为怪异的是:每逢下雨天，山谷之中就隐隐有紫气出现。]],["enterable"]=1,["id"]=[[fb18_40]],["leftDown"]=[[fb18_39]],["name"]=[[紫气台]],["permission"]=2,["right"]=[[fb18_41]],["role1"]=[[fb18r40_1]],["role2"]=[[dr3npc14b]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_41"]={["dsc"]=[[这里是朝阳峰小路，山势陡峭，两边下临深谷，一不小心都会掉了下去。西面有一条小路，长草没径。]],["enterable"]=1,["id"]=[[fb18_41]],["item1"]=[[dr3wp09a]],["left"]=[[fb18_40]],["name"]=[[朝阳峰小路]],["permission"]=2,["right"]=[[fb18_42]],["role1"]=[[fb18r41_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_42"]={["dsc"]=[[这里就是华山的东峰，也称朝阳峰，是华山看日出的绝佳处。於此俯瞰，黄河隐显东迤如带，南望小孤峰背倚山河。小孤峰上有一小亭，那就是华山著名的“博台”了。东壁悬崖上，更有一个巨型掌印，相传为「河神巨灵」劈山时所留下的，李白诗中“巨灵咆哮劈两山，洪波喷流射东海”就是指这个上古传说。]],["enterable"]=1,["id"]=[[fb18_42]],["item1"]=[[fb18item100]],["left"]=[[fb18_41]],["name"]=[[朝阳峰]],["permission"]=2,["role1"]=[[fb18r42_1]],["role2"]=[[fb18r42_100]],["role3"]=[[fb18r42_101]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_44"]={["down"]=[[fb18_36]],["dsc"]=[[这是华山掌门的居所「有所不为轩」，此处是前厅，厅上挂着「正气堂」三字匾额。厅中很宽敞，却没什么摆设，靠墙放着两把交椅，这里是掌门议事、授徒的地方，后面是寝室。]],["enterable"]=1,["id"]=[[fb18_44]],["name"]=[[有所不为轩]],["permission"]=1,["role1"]=[[fb18r44_1]],["role2"]=[[fb18r44_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_60"]={["dsc"]=[[这是一片松树林。中间一条小路，两边都是黑森森的几丈高的松树。快出林了，可以看到东边好高的一道大山。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb18_60]],["item1"]=[[fb18item21]],["item2"]=[[fb18item14]],["item3"]=[[fb18item21]],["leftDown"]=[[fb18_02]],["name"]=[[松树林]],["permission"]=2,["right"]=[[fb18_61]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_61"]={["dsc"]=[[你来到中条山脚。仰望天空，山势压顶，天边的红霞映透了整个山林，呼啸的穿山风刮个不停。你不禁有些惧意。向东有一条上山小路。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb18_61]],["left"]=[[fb18_60]],["name"]=[[中条山脚]],["permission"]=2,["right"]=[[fb18_62]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_62"]={["dsc"]=[[你走在中条山路上。路径狭小，周围茂密森林里，传来阵阵野兽夜禽的嘶鸣，听来让人毛骨悚然。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb18_62]],["item1"]=[[fb18item21]],["item2"]=[[fb18item21]],["item3"]=[[fb18item21]],["left"]=[[fb18_61]],["name"]=[[中条山森林]],["permission"]=2,["right"]=[[fb18_63]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_63"]={["down"]=[[fb18_79]],["dsc"]=[[山路越来越小，周围茂密森林里和脚下的茅草封住了路，上不见天光，后不见归路，你简直绝望了。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb18_63]],["item1"]=[[fb18item21]],["item2"]=[[fb18item14]],["item3"]=[[24maskjqcf01]],["left"]=[[fb18_62]],["name"]=[[中条山密林]],["permission"]=2,["rightUp"]=[[fb18_64]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_64"]={["dsc"]=[[树林外，赫然站着一个汉子，在阴森森的林子边上，凭添一股煞气。西上是登山的路，东边就进入森林了。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb18_64]],["item1"]=[[fb18item21]],["leftDown"]=[[fb18_63]],["name"]=[[树林外]],["permission"]=2,["right"]=[[fb18_65]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_65"]={["dsc"]=[[你走在峭壁边的小路上。一侧是密密的丛林，外侧却是极深的陡壁。山风凛冽，几乎要把你刮落崖去。]],["enterable"]=1,["id"]=[[fb18_65]],["left"]=[[fb18_64]],["name"]=[[峭壁]],["permission"]=2,["rightDown"]=[[fb18_66]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_66"]={["down"]=[[fb18_67]],["dsc"]=[[这里是中条山的一个隐秘山谷。四周是高可及天的山峰，云深林密，一径小溪潺潺流过，溅入坡下塘中。溪畔有一汉子舞剑正酣。不打扰的为妙。]],["enterable"]=1,["id"]=[[fb18_66]],["leftUp"]=[[fb18_65]],["name"]=[[山谷]],["permission"]=2,["role1"]=[[fb18r66_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb18_67"]={["down"]=[[fb18_68]],["dsc"]=[[你走在中条山山间平地上。靠东山壁上有一小屋。传闻当年华山玉女峰剑气两宗大对决，中计败北的剑宗弟子大多隐匿中条山。难道就是这里？林中冷风轻吹门响。很失意的感觉。]],["enterable"]=1,["id"]=[[fb18_67]],["name"]=[[山间平地]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb18_66]],["visible"]=1},["fb18_68"]={["dsc"]=[[这里就是华山剑宗的的根本之地。二十五年来，剑宗弟子卧薪尝胆，只是为了夺回华山门派掌门，为此，付出了极大牺牲。屋里陈设极为简陋。这么多年来一直没有长久隐匿的念头使得剑宗弟子能忍辱负重，只待重开生天。]],["enterable"]=1,["id"]=[[fb18_68]],["name"]=[[林间小屋]],["permission"]=2,["role1"]=[[fb18r68_2]],["role2"]=[[fb18r68_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_67]],["visible"]=1},["fb18_69"]={["dsc"]=[[这里空间不大，只能容得下数人，周遭的石壁透着些许寒气，让人十分不舒服。]],["id"]=[[fb18_69]],["name"]=[[阴寒洞穴]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb18_70]]},["fb18_70"]={["down"]=[[fb18_69]],["dsc"]=[[这里空间不大，只能容得下数人，周遭的石壁透着些许寒气，让人十分不舒服。]],["id"]=[[fb18_70]],["item1"]=[[wabaorenwu1]],["name"]=[[阴寒洞穴]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb18_71]]},["fb18_71"]={["down"]=[[fb18_70]],["dsc"]=[[这里空间不大，只能容得下数人，周遭的石壁透着些许寒气，让人十分不舒服。]],["id"]=[[fb18_71]],["name"]=[[阴寒洞穴]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb18_72]]},["fb18_72"]={["down"]=[[fb18_71]],["dsc"]=[[这里空间不大，只能容得下数人，周遭的石壁透着些许寒气，让人十分不舒服。]],["id"]=[[fb18_72]],["item1"]=[[wabaorenwu10]],["name"]=[[阴寒洞穴]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb18_73]]},["fb18_73"]={["down"]=[[fb18_72]],["dsc"]=[[这里空间不大，只能容得下数人，周遭的石壁透着些许寒气，让人十分不舒服。]],["id"]=[[fb18_73]],["name"]=[[阴寒洞穴]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb18_74]]},["fb18_74"]={["down"]=[[fb18_73]],["dsc"]=[[这里空间不大，只能容得下数人，周遭的石壁透着些许寒气，让人十分不舒服。]],["id"]=[[fb18_74]],["item1"]=[[wabaorenwu19]],["name"]=[[阴寒洞穴]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb18_75"]={["dsc"]=[[山洪瀑布旁一条草丛向内延伸，再往前走便是一条青石铺就的小路。小路上水汽腾腾，有些看不清四周风景。]],["id"]=[[fb18_75]],["item1"]=[[fb18item113]],["item2"]=[[2019qxhdd1]],["leftUp"]=[[fb18_04]],["name"]=[[瀑布小路]],["permission"]=2,["right"]=[[fb18_76]],["stepMusic"]=[[jiaobu]]},["fb18_76"]={["dsc"]=[[瀑布旁隐蔽小路之后的村子。远远望去村中毫无人烟，很多房屋已经成为碎瓦。村中传来阵阵恶臭。]],["id"]=[[fb18_76]],["item1"]=[[fb18item107]],["item2"]=[[fb18item108]],["left"]=[[fb18_75]],["name"]=[[村口]],["permission"]=2,["right"]=[[fb18_77]],["role1"]=[[fb18r76_100]],["stepMusic"]=[[jiaobu]]},["fb18_77"]={["dsc"]=[[村子中央的广场。广场正中被挖开了一个很大的土坑，稍微挖开一点，便可以看到下面全部埋的是尸体，大多数已经烧焦。]],["id"]=[[fb18_77]],["item1"]=[[fb18item109]],["left"]=[[fb18_76]],["name"]=[[村广场]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb18_78]]},["fb18_78"]={["down"]=[[fb18_77]],["dsc"]=[[一件普通的民居，门半掩着，屋内物品凌乱不堪。往里走是一张木床，床后隐隐传来女子的哭声。]],["id"]=[[fb18_78]],["item1"]=[[fb18item110]],["item2"]=[[fb18item111]],["name"]=[[民居]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb18_79"]={["dsc"]=[[沐家父子用来锻造的地方。在木屋之前开了一小块空地，搭建上木棚，里面放着打铁炉、锻造台和淬炼的水槽，木棚的一角堆着细铁砂与柴火。一个木架上放着各式打造的工具。]],["id"]=[[fb18_79]],["name"]=[[打铁坪]],["permission"]=2,["right"]=[[fb18_80]],["role1"]=[[sbitem4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_63]]},["fb18_80"]={["dsc"]=[[一座隐藏在华山密林之中的小木屋。虽然外表有修补的痕迹，但里里外外都整齐干净，收拾得井井有条。木屋门口圈养着几只鸡，另一旁则养着花草，花草之间有石凳石桌。]],["id"]=[[fb18_80]],["left"]=[[fb18_79]],["name"]=[[木屋]],["permission"]=2,["role1"]=[[sbr79_1]],["role2"]=[[sbr79_2]],["role3"]=[[sbr79_3]],["stepMusic"]=[[jiaobu]]},["fb18_81"]={["dsc"]=[[此处乃是峭壁之上，向下看不见谷底，向上触手可及青云。依靠悬崖处有一方突出崖壁数尺的巨岩，巨岩之上被人修理平整，堆放着一些柴火、铁矿之物。巨岩之后是一处洞穴，可容一人通行，里面似乎很深。]],["id"]=[[fb18_81]],["left"]=[[fb18_82]],["name"]=[[悬崖]],["permission"]=2,["role1"]=[[fb18dj2]],["stepMusic"]=[[jiaobu]]},["fb18_82"]={["dsc"]=[[往巨岩之后一路走，不多时眼前的景色豁然开朗。此处乃是一处天然岩洞，岩洞约有数十丈宽，洞顶四周悬挂着钟乳岩，地上也生出不少石笋。洞内正中摆放着锻造兵器的石台，一捧月光正从洞顶的开口处洒落到石台之上，将洞穴之内照得分外通明。]],["id"]=[[fb18_82]],["name"]=[[洞穴]],["permission"]=2,["right"]=[[fb18_81]],["role1"]=[[fb18sbnpc_1]],["role2"]=[[fb18sbnpc_2]],["stepMusic"]=[[jiaobu]]},["fb18_83"]={["dsc"]=[[华山之巅临于苍穹之下，四周遗留了不少豪杰当年比剑后破损的神兵。每至夜晚凄寒无比，狂风掠过如刀剑嘶鸣，恍惚间仍能看到当年比剑之景。]],["id"]=[[fb18_83]],["item1"]=[[fb18dj4]],["left"]=[[fb18_35]],["name"]=[[华山之巅]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb18_84"]={["down"]=[[fb18_10]],["dsc"]=[[弯弯曲曲的石路不知通往何方。]],["id"]=[[fb18_84]],["name"]=[[石路]],["permission"]=2,["role1"]=[[fb18_33a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb18_85]]},["fb18_85"]={["down"]=[[fb18_84]],["dsc"]=[[宽敞的道路，以石板铺就，蜿蜒通向朝阳峰顶。]],["id"]=[[fb18_85]],["item1"]=[[fubentiaozhuan1]],["name"]=[[朝阳峰小路]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb18_86"]={["dsc"]=[[这是间小小的密室，放有打坐练功的蒲团，布置简陋，被打扫得十分干净。]],["enterable"]=0,["id"]=[[fb18_86]],["item1"]=[[dr3wp05a]],["item2"]=[[dr3wp06a]],["left"]=[[fb18_27]],["name"]=[[密室]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=0}}0